def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); out=[r[:] for r in grid]
    for r in range(h):
      for c in range(w):
        if grid[r][c]==8 or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); cells=[]
        while stack:
          y,x=stack.pop(); cells.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            yy,xx=y+dy,x+dx
            if 0<=yy<h and 0<=xx<w and grid[yy][xx]!=8 and (yy,xx) not in seen:
              seen.add((yy,xx)); stack.append((yy,xx))
        y0=min(y for y,x in cells); y1=max(y for y,x in cells); x0=min(x for y,x in cells); x1=max(x for y,x in cells)
        colored=[(y,x) for y,x in cells if grid[y][x] not in (0,8)]
        if not colored: continue
        a=min(y for y,x in colored); b=max(y for y,x in colored); l=min(x for y,x in colored); d=max(x for y,x in colored)
        # colored motif bounding box; repeat over component's rectangular footprint
        th,tw=b-a+1,d-l+1
        tile=[[grid[a+i][l+j] for j in range(tw)] for i in range(th)]
        for y in range(y0,y1+1):
          for x in range(x0,x1+1):
            if grid[y][x]!=8:
              out[y][x]=tile[(y-y0)%th][(x-x0)%tw]
    return out
